import React, { useEffect, useState } from 'react';
import { getStudents, getSubjects, submitMarks } from '../api/api';

function MarksForm({ onMarksSubmitted }) {
  const [students, setStudents] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [selectedStudent, setSelectedStudent] = useState('');
  const [marksValues, setMarksValues] = useState({});
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [serverError, setServerError] = useState(null);
  const [successMsg, setSuccessMsg] = useState(null);

  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    setLoading(true);
    setLoadError(null);
    try {
      const [studentsData, subjectsData] = await Promise.all([getStudents(), getSubjects()]);
      setStudents(studentsData);
      setSubjects(subjectsData);
    } catch (err) {
      setLoadError(err.message);
    } finally {
      setLoading(false);
    }
  }

  function handleMarksChange(subjectId, value) {
    setMarksValues(prev => ({ ...prev, [subjectId]: value }));
    setErrors(prev => ({ ...prev, [subjectId]: undefined }));
  }

  function validate() {
    const errs = {};
    if (!selectedStudent) errs.student = 'Please select a student';

    subjects.forEach(subj => {
      const val = marksValues[subj.id];
      if (val === undefined || val === '') {
        errs[subj.id] = 'Required';
      } else {
        const num = Number(val);
        if (Number.isNaN(num)) errs[subj.id] = 'Must be a number';
        else if (num < 0 || num > subj.max_marks) errs[subj.id] = `Must be 0-${subj.max_marks}`;
      }
    });
    return errs;
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setServerError(null);
    setSuccessMsg(null);

    const validationErrors = validate();
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    setSubmitting(true);
    try {
      const marks = subjects.map(s => ({
        subject_id: s.id,
        marks_obtained: Number(marksValues[s.id])
      }));
      await submitMarks({ student_id: Number(selectedStudent), marks });
      setSuccessMsg('Marks submitted successfully.');
      setMarksValues({});
      if (onMarksSubmitted) onMarksSubmitted(Number(selectedStudent));
    } catch (err) {
      setServerError(err.message);
    } finally {
      setSubmitting(false);
    }
  }

  if (loading) return <div className="state-message">Loading form...</div>;
  if (loadError) return <div className="state-message error">{loadError} <button onClick={loadData}>Retry</button></div>;

  return (
    <div className="card">
      <h2>Enter Marks</h2>
      {students.length === 0 ? (
        <div className="state-message">Add a student first before entering marks.</div>
      ) : (
        <form onSubmit={handleSubmit} noValidate>
          <div className="form-group">
            <label htmlFor="student">Student</label>
            <select
              id="student"
              value={selectedStudent}
              onChange={(e) => { setSelectedStudent(e.target.value); setErrors(prev => ({ ...prev, student: undefined })); }}
            >
              <option value="">-- Select a student --</option>
              {students.map(s => (
                <option key={s.id} value={s.id}>{s.name} ({s.roll_no})</option>
              ))}
            </select>
            {errors.student && <span className="field-error">{errors.student}</span>}
          </div>

          <div className="marks-grid">
            {subjects.map(subj => (
              <div className="form-group" key={subj.id}>
                <label htmlFor={`subj-${subj.id}`}>{subj.name} (out of {subj.max_marks})</label>
                <input
                  id={`subj-${subj.id}`}
                  type="number"
                  min="0"
                  max={subj.max_marks}
                  value={marksValues[subj.id] ?? ''}
                  onChange={(e) => handleMarksChange(subj.id, e.target.value)}
                />
                {errors[subj.id] && <span className="field-error">{errors[subj.id]}</span>}
              </div>
            ))}
          </div>

          {serverError && <div className="state-message error">{serverError}</div>}
          {successMsg && <div className="state-message success">{successMsg}</div>}

          <button type="submit" className="btn-primary" disabled={submitting}>
            {submitting ? 'Submitting...' : 'Submit Marks'}
          </button>
        </form>
      )}
    </div>
  );
}

export default MarksForm;
